import { NextResponse } from "next/server";
import { cookieName, tokenPruefen } from "@/lib/plattform/sitzung";

// Portal-Schutz: /portal/** nur mit gültig signiertem Sitzungscookie, sonst
// Weiterleitung zu /login?weiter=… (nur interne Pfade). Die Middleware prüft
// Signatur und Ablauf; Rollen, Sperre und Sitzungsversion prüfen Seiten und
// APIs bei jedem Aufruf frisch gegen das Backend.
// Sichere Kopfzeilen für Portal, Anmeldung, Einladungen und Plattform-APIs (Login, Sicherheit & Teams):
// kein Einbetten (Clickjacking), eigener Browsing-Kontext, kein Referrer bei Token-Links, HSTS in Produktion.
function sicherheitsKopf(res, pathname) {
  const h = res.headers;
  h.set("X-Frame-Options", "DENY");
  h.set("Content-Security-Policy", "frame-ancestors 'none'; base-uri 'self'; form-action 'self'; object-src 'none'");
  h.set("Cross-Origin-Opener-Policy", "same-origin");
  h.set("X-Content-Type-Options", "nosniff");
  h.set("Permissions-Policy", "camera=(), microphone=(), geolocation=(self), payment=(), usb=()");
  const tokenSeite = ["/login/link", "/einladung/", "/passwort-vergessen", "/api/auth/"].some((p) => pathname.startsWith(p));
  h.set("Referrer-Policy", tokenSeite ? "no-referrer" : "strict-origin-when-cross-origin");
  if (!pathname.startsWith("/api/")) h.set("Cache-Control", "no-store");
  if (process.env.NODE_ENV === "production") h.set("Strict-Transport-Security", "max-age=63072000; includeSubDomains");
  return res;
}

export async function middleware(request) {
  const { pathname, search } = request.nextUrl;
  // Nicht-Portal-Pfade (Anmeldung, Einladung, APIs): nur Kopfzeilen, keine Sitzungsprüfung hier
  if (pathname !== "/portal" && !pathname.startsWith("/portal/")) return sicherheitsKopf(NextResponse.next(), pathname);
  const token = request.cookies.get(cookieName())?.value;

  let gueltig = false;
  try {
    gueltig = !!(await tokenPruefen(token));
  } catch (e) {
    // z. B. SESSION_SECRET fehlt in Produktion – nie ohne Prüfung durchlassen
    console.error("[plattform] Sitzungsprüfung fehlgeschlagen:", e?.message);
  }

  if (!gueltig) {
    const ziel = new URL("/login", request.url);
    ziel.searchParams.set("weiter", `${pathname}${search}`.slice(0, 300));
    const res = NextResponse.redirect(ziel);
    if (token) res.cookies.delete(cookieName());
    return sicherheitsKopf(res, pathname);
  }

  // Aktuellen Pfad an Server-Komponenten weiterreichen (für ?weiter= bei abgelaufener Sitzung)
  const kopf = new Headers(request.headers);
  kopf.set("x-oi-pfad", `${pathname}${search}`.slice(0, 300));
  return sicherheitsKopf(NextResponse.next({ request: { headers: kopf } }), pathname);
}

export const config = {
  matcher: ["/portal", "/portal/:path*", "/login", "/login/:path*", "/registrieren", "/passwort-vergessen", "/einladung/:path*", "/api/auth/:path*", "/api/portal/:path*"],
};
/** @type {import('next').NextConfig} */
const nextConfig = {
  // Ausgabeverzeichnis umschaltbar (wie oekovolt.de): Build-Verifikation läuft
  // mit NEXT_DIST_DIR=.next-verify neben einem laufenden Server.
  distDir: process.env.NEXT_DIST_DIR || ".next",
  trailingSlash: false,
  compress: true,
  poweredByHeader: false,

  async headers() {
    const sicherheit = [
      { key: "X-Content-Type-Options", value: "nosniff" },
      { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
      { key: "X-Frame-Options", value: "SAMEORIGIN" },
      { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=(self)" },
    ];
    return [
      { source: "/:path*", headers: sicherheit },
      // Portal und Login nie in Suchmaschinen, nie zwischenspeichern
      { source: "/portal/:path*", headers: [{ key: "X-Robots-Tag", value: "noindex, nofollow" }, { key: "Cache-Control", value: "no-store" }] },
      ...["/login", "/registrieren", "/passwort-vergessen"].map((source) => ({ source, headers: [{ key: "X-Robots-Tag", value: "noindex, follow" }] })),
    ];
  },
};

export default nextConfig;
// src/lib/herkunft.js
//
// Kampagnen-Zuordnung für Anfragen – bewusst OHNE Cookies und OHNE Browserspeicher:
// Beim ersten Seitenaufruf werden UTM-Parameter, verweisende Domain und Einstiegsseite
// im Arbeitsspeicher der geöffneten Website gehalten (bleibt bei Navigation innerhalb der Seite
// erhalten, endet beim Schließen/Neuladen). Übertragen wird nur zusammen mit einer Anfrage.

let erfasst = null;

const UTM = ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content"];
const kurz = (v, n = 100) => String(v || "").replace(/[^\p{L}\p{N} _.\-/:+|]/gu, "").slice(0, n);

function eigeneDomain(host) {
  return /(^|\.)oekoinvest\.(com|at|de|ch)$/.test(host) || host === location.host;
}

/** Einmalig beim ersten Laden aufrufen (HerkunftErfassen in LayoutWrapper). */
export function herkunftErfassen() {
  if (typeof window === "undefined" || erfasst) return;
  const url = new URL(window.location.href);
  const utm = Object.fromEntries(UTM.map((k) => [k, kurz(url.searchParams.get(k))]).filter(([, v]) => v));

  let referrer = "";
  try {
    const r = document.referrer ? new URL(document.referrer) : null;
    if (r && !eigeneDomain(r.host)) referrer = r.host.replace(/^www\./, "");
  } catch {
    /* ungültig */
  }

  // Einmal-Tokens nie übernehmen
  const einstieg = url.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200);
  erfasst = { ...utm, referrer, einstieg, zeit: new Date().toISOString() };
}

/** Kanal grob klassifizieren (für Auswertungen). */
function kanal(h) {
  const medium = (h.utm_medium || "").toLowerCase();
  if (h.utm_source || h.utm_medium) {
    if (/cpc|ppc|paid|ads?$/.test(medium)) return "Anzeige";
    if (/social/.test(medium)) return "Social Media";
    if (/mail|newsletter/.test(medium)) return "E-Mail";
    if (/qr|print|flyer|offline/.test(medium)) return "Offline/QR";
    return "Kampagne";
  }
  const r = h.referrer || "";
  if (!r) return "Direkt";
  if (/google\.|bing\.|duckduckgo\.|ecosia\.|yahoo\.|qwant\./.test(r)) return "Suchmaschine";
  if (/chatgpt\.com|openai\.com|perplexity\.ai|claude\.ai|gemini\.google|copilot\.microsoft/.test(r)) return "KI-Assistent";
  if (/facebook\.|instagram\.|linkedin\.|xing\.|t\.co$|x\.com|threads\.net|mastodon|social\.|youtube\./.test(r)) return "Social Media";
  return "Verweis";
}

/** Daten zum Mitsenden mit einer Anfrage. `seite` = aktuelle Seite. */
export function herkunft() {
  if (typeof window === "undefined") return null;
  if (!erfasst) herkunftErfassen();
  const h = erfasst || {};
  return { ...h, kanal: kanal(h), seite: window.location.pathname.replace(/^\/(scan|fortsetzen)\/.*/, "/$1").slice(0, 200) };
}

/** Kompakte Textzeile für Backends ohne eigene Felder (z. B. bestehende Kontaktanfrage). */
export function herkunftText(h = herkunft()) {
  if (!h) return "";
  const teile = [
    `Kanal: ${h.kanal}`,
    h.utm_source && `Quelle: ${h.utm_source}`,
    h.utm_medium && `Medium: ${h.utm_medium}`,
    h.utm_campaign && `Kampagne: ${h.utm_campaign}`,
    h.utm_term && `Keyword: ${h.utm_term}`,
    h.referrer && `Verweis: ${h.referrer}`,
    h.einstieg && `Einstieg: ${h.einstieg}`,
    h.seite && `Seite: ${h.seite}`,
  ].filter(Boolean);
  return `[Herkunft] ${teile.join(" · ")}`;
}

